void cmd_init (const UInt8 cmd_pip_size , const UInt8 cmd_q_free_size )
{
	UInt8 n ;
	
	if(!cmd_init_nvfs())
    {
        //error ?
    }
	cmd_exec_table = reg_q_table_create( cmd_q_free_size ) ; 
	
	cmd_q_pending  = q_create () ;
	cmd_q_free     = q_create () ;
	
	for (n = 0 ; n < cmd_pip_size ; n++)
	{
		exec_q_free_add( cmd_q_free , sizeof( Cmd_Q_Msg) );
	}

    cmd_lut_clr_mode( (Exec_Mode)(EXEC_MODE_NORMAL | EXEC_MODE_PROG) ) ; 

    cmd_lut_set_mode( EXEC_MODE_NORMAL );
	
	tsk_cmd = os_tsk_create (cmd_task , TASK_CMD_PRI , CMD_STACK , 0 , TASK_CMD_NAME) ;
	
	os_tsk_start (tsk_cmd , 0) ;
}

